const allowed=new Set(['REPLACE_GMAIL_WORKFLOW_ID','REPLACE_DRIVE_WORKFLOW_ID','REPLACE_TELEGRAM_WORKFLOW_ID','REPLACE_BANK_WORKFLOW_ID','REPLACE_REVIEW_WORKFLOW_ID','REPLACE_REGISTER_SYNC_WORKFLOW_ID','REPLACE_COMMAND_PROCESSOR_WORKFLOW_ID','REPLACE_BILLDU_PROBE_WORKFLOW_ID']);
const workflowId=String($json.workflow?.id||'');
if(!allowed.has(workflowId))return [];
const workflowName=String($json.workflow?.name||workflowId);
const executionId=String($json.execution?.id||'neznáme');
const lastNode=String($json.execution?.lastNodeExecuted||'neznámy uzol');
const message=String($json.execution?.error?.message||$json.error?.message||'Neznáma chyba').replace(/[\r\n]+/g,' ').slice(0,500);
const occurredAt=new Date().toLocaleString('sk-SK',{timeZone:'Europe/Bratislava'});
return [{json:{text:'⚠️ SARA Finance — chyba workflowu\n'+workflowName+'\nUzol: '+lastNode+'\nExecution: '+executionId+'\nČas: '+occurredAt+'\nChyba: '+message}}];
